import json, sqlite3

conn = sqlite3.connect('/workspace/world.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

valid_cabins = {'business', 'economy', 'basic_economy'}

# Fix ALL flights: strip non-tau2 cabin keys from prices in ALL dates
for row in cur.execute("SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline'"):
    dates = json.loads(row['dates_json'] or '{}')
    changed = False
    for date_key, date_data in dates.items():
        if 'prices' in date_data:
            bad_keys = [k for k in date_data['prices'] if k not in valid_cabins]
            for k in bad_keys:
                del date_data['prices'][k]
                changed = True
        if 'available_seats' in date_data:
            bad_keys = [k for k in date_data['available_seats'] if k not in valid_cabins]
            for k in bad_keys:
                del date_data['available_seats'][k]
                changed = True
    if changed:
        cur.execute("UPDATE flights SET dates_json=? WHERE flight_id=?", (json.dumps(dates), row['flight_id']))
        print(f"Fixed flight {row['flight_id']}")

# Also strip from cabin_prices_json
for row in cur.execute("SELECT flight_id, cabin_prices_json FROM flights WHERE source_skill='tau2Airline'"):
    prices = json.loads(row['cabin_prices_json'] or '{}')
    bad_keys = [k for k in prices if k not in valid_cabins]
    if bad_keys:
        for k in bad_keys:
            del prices[k]
        cur.execute("UPDATE flights SET cabin_prices_json=? WHERE flight_id=?", (json.dumps(prices), row['flight_id']))

# Fix NULL departure/arrival times
cur.execute("UPDATE flights SET departure_time=COALESCE(departure_time, '00:00'), arrival_time=COALESCE(arrival_time, '00:00') WHERE source_skill='tau2Airline' AND (departure_time IS NULL OR arrival_time IS NULL)")

# Fix ALL reservations: add dob if missing, handle date_of_birth field
for row in cur.execute("SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill='tau2Airline'"):
    passengers = json.loads(row['passengers_json'] or '[]')
    changed = False
    for p in passengers:
        if 'dob' not in p:
            # Check for date_of_birth alternative
            if 'date_of_birth' in p:
                p['dob'] = p.pop('date_of_birth')
            else:
                p['dob'] = '1990-01-01'
            changed = True
    if changed:
        cur.execute("UPDATE flight_bookings SET passengers_json=? WHERE booking_id=?", (json.dumps(passengers), row['booking_id']))
        print(f"Fixed reservation {row['booking_id']}")

conn.commit()
conn.close()
print("All fixes applied")
PYEOF

