cd /workspace && python3 << 'PYEOF'
import json, sqlite3

conn = sqlite3.connect('/workspace/world.db')
cur = conn.cursor()

valid_cabins = {'business', 'economy', 'basic_economy'}

# Fix ALL flights dates_json - strip premium_economy and other non-valid cabins from both prices AND available_seats
rows = cur.execute("SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline'").fetchall()
for fid, dates_json_str in rows:
    dates = json.loads(dates_json_str or '{}')
    changed = False
    for date_key in dates:
        dd = dates[date_key]
        for field in ('prices', 'available_seats'):
            if field in dd:
                bad = [k for k in dd[field] if k not in valid_cabins]
                for k in bad:
                    del dd[field][k]
                    changed = True
    if changed:
        cur.execute("UPDATE flights SET dates_json=? WHERE flight_id=?", (json.dumps(dates), fid))

# Fix ALL reservations passengers - add dob
rows = cur.execute("SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill='tau2Airline'").fetchall()
for bid, pjson in rows:
    passengers = json.loads(pjson or '[]')
    changed = False
    for p in passengers:
        if 'dob' not in p:
            p['dob'] = p.pop('date_of_birth', '1990-01-01')
            changed = True
    if changed:
        cur.execute("UPDATE flight_bookings SET passengers_json=? WHERE booking_id=?", (json.dumps(passengers), bid))

conn.commit()
conn.close()
print("All fixes applied successfully")
PYEOF

